/**
 * Completion and hover data for the data formats of `<marshal>`, `<unmarshal>` and `<dataFormat>`.
 * The format list is generated by `redb-route-xml elements` (media/redb-route-dataformats.json): each
 * format's registered name, its type name and the options it takes in attribute form. The XSD cannot
 * make attributes depend on the `type=` value, so these hints are served here, from that list.
 */

/** One option of a data format in attribute form. */
export interface FormatAttribute {
    name: string;
    kind: string;
    enumValues?: string[];
    default?: string;
    description?: string;
}

/** One data format of the generated list. A format without a registered name has no `format=` value. */
export interface DataFormatInfo {
    name?: string;
    type: string;
    contentType?: string;
    mediaTypes?: string[];
    attributes?: FormatAttribute[];
    unmarshalTargets?: string[];
}

/** The elements that name a data format, by local name. */
const FORMAT_ELEMENTS = new Set(["marshal", "unmarshal", "dataFormat"]);

/** One attribute of a start tag, with its offsets in the document. */
export interface TagAttribute {
    name: string;
    nameStart: number;
    nameEnd: number;
    /** Offset of the first character of the value, or -1 when the attribute has no value yet. */
    valueStart: number;
    /** Offset just past the value (before the closing quote, or the end of the scan when unclosed). */
    valueEnd: number;
    value: string;
}

/** A start tag of the document, possibly unfinished while it is being typed. */
export interface StartTag {
    /** Local name of the element. */
    element: string;
    open: number;
    attributes: TagAttribute[];
}

/**
 * The start tag the offset sits in, or null outside one. The tag is read quote-aware up to its `>`; an
 * unfinished tag ends at the next `<` outside a value, so the following tags are not read as its
 * attributes. Comments, CDATA, declarations and end tags are not start tags.
 */
export function startTagAt(text: string, offset: number): StartTag | null {
    const before = text.slice(0, offset);
    const commentStart = before.lastIndexOf("<!--");
    if (commentStart >= 0 && before.indexOf("-->", commentStart) < 0)
        return null;
    const cdataStart = before.lastIndexOf("<![CDATA[");
    if (cdataStart >= 0 && before.indexOf("]]>", cdataStart) < 0)
        return null;

    // The innermost '<' before the offset that is not inside a quoted value of an earlier tag.
    let open = before.lastIndexOf("<");
    while (open >= 0 && insideQuotedValue(text, open))
        open = before.lastIndexOf("<", open - 1);
    if (open < 0)
        return null;
    const nameMatch = /^<([A-Za-z_][\w.\-]*(?::[\w.\-]+)?)/.exec(text.slice(open, open + 200));
    if (!nameMatch)
        return null;

    const attributes: TagAttribute[] = [];
    let i = open + nameMatch[0].length;
    let end = -1;
    while (i < text.length) {
        const c = text[i];
        if (/\s/.test(c)) { i++; continue; }
        if (c === ">") { end = i; break; }
        if (c === "/" && text[i + 1] === ">") { end = i + 1; break; }
        if (c === "<") break;
        const name = /^[^\s=/>"'<]+/.exec(text.slice(i, i + 200));
        if (!name) { i++; continue; }
        const attribute: TagAttribute = {
            name: localName(name[0]), nameStart: i, nameEnd: i + name[0].length,
            valueStart: -1, valueEnd: -1, value: "",
        };
        i = attribute.nameEnd;
        while (i < text.length && /\s/.test(text[i])) i++;
        if (text[i] === "=") {
            i++;
            while (i < text.length && /\s/.test(text[i])) i++;
            const quote = text[i];
            if (quote === '"' || quote === "'") {
                const close = text.indexOf(quote, i + 1);
                attribute.valueStart = i + 1;
                attribute.valueEnd = close < 0 ? text.length : close;
                attribute.value = text.slice(attribute.valueStart, attribute.valueEnd);
                i = close < 0 ? text.length : close + 1;
            }
        }
        attributes.push(attribute);
    }
    if (end >= 0 && end < offset)
        return null;
    return { element: localName(nameMatch[1]), open, attributes };
}

/** Whether the offset of a '<' lies inside a quoted value of the tag before it. */
function insideQuotedValue(text: string, at: number): boolean {
    const previous = text.lastIndexOf("<", at - 1);
    if (previous < 0)
        return false;
    let quote: string | null = null;
    for (let i = previous + 1; i < at; i++) {
        const c = text[i];
        if (quote) { if (c === quote) quote = null; }
        else if (c === '"' || c === "'") quote = c;
        else if (c === ">") return false;
    }
    return quote !== null;
}

function localName(name: string): string {
    return name.slice(name.indexOf(":") + 1);
}

/** Type names compare without whitespace and case: `A.B, Asm` and `a.b,asm` name the same format. */
function sameType(a: string, b: string): boolean {
    const norm = (s: string) => s.replace(/\s+/g, "").toLowerCase();
    return norm(a) === norm(b);
}

/** The format a data-format tag names through `type=`, or through `format=` for the target list. */
function formatOf(tag: StartTag, formats: readonly DataFormatInfo[], byName: boolean): DataFormatInfo | undefined {
    const type = tag.attributes.find(a => a.name === "type" && a.valueStart >= 0);
    if (type)
        return formats.find(f => sameType(f.type, type.value));
    if (!byName)
        return undefined;
    const format = tag.attributes.find(a => a.name === "format" && a.valueStart >= 0);
    return format ? formats.find(f => f.name !== undefined && f.name.toLowerCase() === format.value.toLowerCase()) : undefined;
}

/** A completion the provider turns into an item. */
export interface FormatCompletion {
    label: string;
    /** "value" replaces the value typed so far; "attribute" inserts `name=""` at the name typed so far. */
    kind: "value" | "attribute";
    replaceFrom: number;
    detail?: string;
    documentation?: string;
}

/**
 * What the offset of a data-format tag takes:
 * - in `format=` of `<marshal>`/`<unmarshal>`: the registered format names;
 * - in `type=` of `<marshal>`/`<unmarshal>`/`<dataFormat>`: the format type names;
 * - in `target=` of `<unmarshal>`: the targets of the format its `type=` or `format=` names;
 * - at an attribute name, once `type=` names a format: its options not yet written;
 * - in the value of such an option: its enum values, or true/false for a Bool;
 * - in the value of a Path option: the files of the module's `resources/` (pathCompletions).
 */
export function formatCompletions(
    text: string, offset: number, formats: readonly DataFormatInfo[],
    resources: () => ResourceTree | null = () => null): FormatCompletion[] {
    const tag = startTagAt(text, offset);
    if (!tag || !FORMAT_ELEMENTS.has(tag.element))
        return [];

    const inValue = tag.attributes.find(a => a.valueStart >= 0 && a.valueStart <= offset && offset <= a.valueEnd);
    if (inValue) {
        const replaceFrom = inValue.valueStart;
        if (inValue.name === "format" && tag.element !== "dataFormat")
            return formats.filter(f => f.name !== undefined).map(f => ({
                label: f.name!, kind: "value", replaceFrom, detail: f.type, documentation: describeFormat(f),
            }));
        if (inValue.name === "type")
            return formats.map(f => ({
                label: f.type, kind: "value", replaceFrom,
                detail: f.name ? `data format ${f.name}` : "data format", documentation: describeFormat(f),
            }));
        if (inValue.name === "target" && tag.element === "unmarshal")
            return (formatOf(tag, formats, true)?.unmarshalTargets ?? []).map(t => ({
                label: t, kind: "value", replaceFrom, detail: "unmarshal target",
            }));
        const option = formatOf(tag, formats, false)?.attributes?.find(a => a.name === inValue.name);
        if (option?.kind === "Path")
            return pathCompletions(tag, option, replaceFrom, resources);
        const values = option?.kind === "Enum" ? option.enumValues ?? [] : option?.kind === "Bool" ? ["true", "false"] : [];
        return values.map(v => ({
            label: v, kind: "value", replaceFrom,
            detail: option!.default === v ? "default" : undefined,
        }));
    }

    // An attribute name: the offset is after whitespace inside the tag, possibly in a name being typed.
    const typed = tag.attributes.find(a => a.nameStart <= offset && offset <= a.nameEnd && a.valueStart < 0);
    if (!typed && tag.attributes.some(a => a.nameStart < offset && offset < a.nameEnd))
        return [];
    const replaceFrom = typed ? typed.nameStart : offset;
    if (!typed && !/\s/.test(text[offset - 1] ?? ""))
        return [];
    const format = formatOf(tag, formats, false);
    if (!format)
        return [];
    const written = new Set(tag.attributes.filter(a => a !== typed).map(a => a.name));
    return (format.attributes ?? []).filter(a => !written.has(a.name)).map(a => ({
        label: a.name, kind: "attribute", replaceFrom,
        detail: attributeDetail(a), documentation: a.description,
    }));
}

/** The hover text at the offset of a data-format tag: an option name, or the format of `type=`/`format=`. */
export function formatHover(text: string, offset: number, formats: readonly DataFormatInfo[]): string | null {
    const tag = startTagAt(text, offset);
    if (!tag || !FORMAT_ELEMENTS.has(tag.element))
        return null;
    const attribute = tag.attributes.find(a =>
        (a.nameStart <= offset && offset < a.nameEnd) || (a.valueStart >= 0 && a.valueStart <= offset && offset < a.valueEnd));
    if (!attribute)
        return null;
    const onName = offset < attribute.nameEnd;
    if (attribute.name === "type" || (attribute.name === "format" && tag.element !== "dataFormat")) {
        if (onName)
            return null;
        const format = attribute.name === "type"
            ? formats.find(f => sameType(f.type, attribute.value))
            : formats.find(f => f.name !== undefined && f.name.toLowerCase() === attribute.value.toLowerCase());
        return format ? describeFormat(format) : null;
    }
    if (!onName)
        return null;
    const option = formatOf(tag, formats, false)?.attributes?.find(a => a.name === attribute.name);
    if (!option)
        return null;
    return `**${option.name}** (${attributeDetail(option)})` + (option.description ? `\n\n${option.description}` : "");
}

function attributeDetail(attribute: FormatAttribute): string {
    const kind = attribute.kind === "Enum" && attribute.enumValues ? attribute.enumValues.join(" | ") : attribute.kind;
    return attribute.default !== undefined ? `${kind}, default ${attribute.default}` : kind;
}

function describeFormat(format: DataFormatInfo): string {
    const lines = [format.name ? `Data format **${format.name}**` : "Data format", "", `\`${format.type}\``];
    if (format.contentType)
        lines.push("", `Content type: ${format.contentType}`);
    const options = format.attributes ?? [];
    if (options.length > 0)
        lines.push("", `Options with \`type=\`: ${options.map(a => a.name).join(", ")}`);
    return lines.join("\n");
}

/**
 * The module's `resources/` folder, the only part of the project folder `redb-route-xml pack` ships
 * besides the routes, `context.xml` and the config stubs. Paths are relative to that folder, with
 * '/' separators; `dirs` holds the folder itself as "".
 */
export interface ResourceTree {
    files: string[];
    dirs: string[];
}

/**
 * The Path options that name a directory, each relative to the directory of the file another option
 * of the same tag names: `schemaRoot=` is read from the schema's directory.
 */
const DIRECTORY_RELATIVE_TO: Readonly<Record<string, string>> = { schemaRoot: "schema" };

/** The resources folder name, which a reference may also spell out (`resources/order.xsd`). */
const RESOURCES_PREFIX = "resources/";

/**
 * Values for a Path option. A file option offers the files under `resources/` in the short form the
 * runtime reads first (`order.xsd` for `resources/order.xsd`). A directory option offers the folders
 * under `resources/` relative to the directory of the file it is read from (`common`, `..`), and
 * nothing while that file is not named, not under `resources/` or still a placeholder.
 */
function pathCompletions(
    tag: StartTag, option: FormatAttribute, replaceFrom: number,
    resources: () => ResourceTree | null): FormatCompletion[] {
    const tree = resources();
    if (!tree)
        return [];
    const base = DIRECTORY_RELATIVE_TO[option.name];
    if (base === undefined)
        return tree.files.map(file => ({ label: file, kind: "value", replaceFrom, detail: "resources/" + file }));

    const named = tag.attributes.find(a => a.name === base && a.valueStart >= 0)?.value.trim().replace(/\\/g, "/");
    if (!named || named.includes("{{") || named.includes("${"))
        return [];
    const file = named.startsWith(RESOURCES_PREFIX) ? named.slice(RESOURCES_PREFIX.length) : named;
    if (!tree.files.includes(file))
        return [];
    const from = file.includes("/") ? file.slice(0, file.lastIndexOf("/")) : "";
    return tree.dirs.filter(dir => dir !== from).map(dir => ({
        label: relativeDir(from, dir), kind: "value", replaceFrom,
        detail: "resources/" + dir + (dir === "" ? "" : "/"),
    }));
}

/** The path from one folder of the tree to another, both relative to its root, with '/' and '..'. */
function relativeDir(from: string, to: string): string {
    const a = from === "" ? [] : from.split("/");
    const b = to === "" ? [] : to.split("/");
    let common = 0;
    while (common < a.length && common < b.length && a[common] === b[common])
        common++;
    return [...a.slice(common).map(() => ".."), ...b.slice(common)].join("/");
}
